CREATE OR REPLACE FUNCTION public.get_master_iq_config() RETURNS SETOF public.iqoption_config LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT c.* FROM public.iqoption_config c WHERE c.is_active AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=c.user_id AND r.role='admin'::public.app_role) ORDER BY c.created_at ASC,c.id ASC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.get_master_iq_config() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_master_iq_config() TO service_role;
DO $$ DECLARE fn text; definition text; old_selection text := 'SELECT * INTO cfg FROM public.iqoption_config WHERE is_active AND user_id IS NOT NULL ORDER BY last_connected_at DESC NULLS LAST LIMIT 1;'; BEGIN FOREACH fn IN ARRAY ARRAY['claim_four_win_reversal','claim_force_loss_win'] LOOP SELECT pg_get_functiondef(p.oid) INTO definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=fn AND pg_get_function_identity_arguments(p.oid)='p_candidate text'; IF definition IS NULL OR strpos(definition,old_selection)=0 THEN RAISE EXCEPTION 'Unexpected selection in %',fn; END IF; EXECUTE replace(definition,old_selection,'SELECT * INTO cfg FROM public.get_master_iq_config();'); END LOOP; END $$;